import { getMetaContent } from "helpers/meta_helpers"

const LOCALE = "en-US"
const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24
const DAYS_SHOWN_RELATIVELY = 7

// Day boundaries default to the timezone the server rendered with (the
// `timezone` meta tag), so they match the server's instead of following the
// browser's resolved timezone, which can differ in a PWA. Pass `null` to use
// the browser's own timezone instead.
export function signedDifferenceInDays(fromDate, toDate, timezone = serverTimezone()) {
  return Math.round((beginningOfDay(toDate, timezone) - beginningOfDay(fromDate, timezone)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date, timezone = serverTimezone()) {
  const { year, month, day } = datePartsInTimezone(date, timezone)
  return new Date(Date.UTC(year, month - 1, day))
}

// Turns a timestamp into words in the browser's own timezone. See
// TimeHelper#local_datetime_tag for the list of styles.
export function formatLocalTime(date, style, now = new Date()) {
  switch (style) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date, now)
    case "full_date":
      return format(date, { month: "short", day: "numeric", year: "numeric" })
    case "weekday":
      return format(date, { weekday: "long", month: "long", day: "numeric" })
    case "datetime":
      return format(date, { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" })
    case "day":
      return formatDay(date, now)
    default:
      return formatRelative(date, now)
  }
}

export function formatFullDateTime(date) {
  return format(date, { weekday: "long", month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" })
}

function formatRelative(date, now) {
  if (signedDifferenceInDays(now, date, null) === 0) {
    return formatTime(date)
  } else {
    return formatDay(date, now)
  }
}

function formatDay(date, now) {
  const days = signedDifferenceInDays(now, date, null)

