import { BridgeComponent } from "@hotwired/hotwire-native-bridge"

export default class extends BridgeComponent {
  static component = "stamp"
  static targets = [ "description" ]
  static values = { scopeSelector: { type: String, default: "body" } }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    this.send("connect", {
      title: this.bridgeElement.title,
      description: this.#description
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  // The description is a <time> filled in by the local-time controller, so
  // watch the stamp's text as well as its attributes to pick up the words once
  // they're rendered.
  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true,
      childList: true,
      characterData: true,
      subtree: true
    })
  }

  get #description() {
    if (this.hasDescriptionTarget) {
      return this.descriptionTarget.textContent.trim()
    } else {
      return this.bridgeElement.bridgeAttribute("description")
    }
  }
}
